function evidenceStatus(e){const status=e.Status||'Pendente';if(status==='Não aplicável')return status;const due=e['Data de validade'];if(due&&due<today())return 'Vencida';return status}
function evidenceDays(e){if(!e['Data de validade'])return '';const d=new Date(e['Data de validade']+'T12:00:00'),t=new Date(today()+'T12:00:00');return Math.round((d-t)/86400000)}
function evidenceNextCode(){evidenceSequence++;return 'EVD-'+String(evidenceSequence).padStart(4,'0')}
function evidencePlans(){return [...new Set([...plans.map(p=>p.plano),...tasks.map(t=>t.plano),...evidences.map(e=>e.Plano)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'))}
function evidenceColor(st){return st==='Disponível'?'ev-green':st==='Vencida'?'ev-red':st==='Em elaboração'||st==='Em análise'?'ev-blue':'ev-gray'}
function evidencesHTML(){
 const all=evidences.filter(e=>(!evidenceFilter.plan||e.Plano===evidenceFilter.plan)&&(!evidenceFilter.status||evidenceStatus(e)===evidenceFilter.status)&&(!evidenceFilter.q||norm(Object.values(e).join(' ')).includes(norm(evidenceFilter.q))));
 const available=evidences.filter(e=>evidenceStatus(e)==='Disponível').length,expired=evidences.filter(e=>evidenceStatus(e)==='Vencida').length;
 return `<section class="evidence-page"><div class="ev-top"><div class="ev-intro">Documentos, comprovações, obrigações e prazos vinculados aos planos.</div><div class="ev-buttons"><button class="secondary" data-evidence-import>Importar lista NR-1 / NR-5</button><button class="primary" data-evidence-add>＋ Nova evidência</button></div></div><div class="ev-kpis"><article><small>Itens cadastrados</small><strong>${evidences.length}</strong></article><article><small>Disponíveis</small><strong class="ev-green-text">${available}</strong></article><article><small>Pendentes / outros</small><strong>${evidences.length-available-expired}</strong></article><article><small>Vencidos</small><strong class="ev-red-text">${expired}</strong></article></div><div class="ev-toolbar"><input id="evSearch" placeholder="Buscar código, documento, norma..." value="${esc(evidenceFilter.q)}"><select id="evPlan"><option value="">Todos os planos</option>${evidencePlans().map(x=>`<option value="${esc(x)}" ${evidenceFilter.plan===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="evStatus"><option value="">Todos os status</option>${['Pendente','Em elaboração','Em análise','Disponível','Vencida','Não aplicável'].map(x=>`<option ${evidenceFilter.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="panel ev-table"><table><thead><tr><th>Código</th><th>Evidência / documento</th><th>Norma</th><th>Órgão que cobra</th><th>Arquivo / link</th><th>Status</th><th>Validade</th><th>Dias p/ vencer</th><th>Ações</th></tr></thead><tbody>${all.map(e=>`<tr><td><b>${esc(e['Código'])}</b></td><td class="ev-document">${esc(e['Evidência / Documento'])}</td><td>${esc(e.Norma)}</td><td class="ev-agency">${esc(e['Órgão que cobra']||'—')}</td><td>${e['Local / link do arquivo']?`<div class="ev-link-actions"><button class="ev-action" data-evidence-openlink="${esc(e['Código'])}" title="Abrir link">↗ Abrir</button><button class="ev-action" data-evidence-copylink="${esc(e['Código'])}" title="Copiar link">⧉ Copiar</button></div>`:'<span class="ev-muted">Não informado</span>'}</td><td><span class="ev-pill ${evidenceColor(evidenceStatus(e))}">${esc(evidenceStatus(e))}</span></td><td>${date(e['Data de validade'])}</td><td>${evidenceDays(e)===''?'—':evidenceDays(e)}</td><td><div class="ev-link-actions"><button class="ev-action ev-view" data-evidence-view="${esc(e['Código'])}">Ver mais</button><button class="ev-action" data-evidence-edit="${esc(e['Código'])}">Editar</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">Nenhuma evidência encontrada. Clique em Nova evidência para cadastrar.</td></tr>'}</tbody></table></div><p class="ev-help">O código é único e não muda ao editar. Os dados são gravados na aba Inventario_Evidencias do Excel conectado. A lista inicial é opcional.</p></section>`;
}
function evidenceView(code){
 const e=evidences.find(x=>x['Código']===code);if(!e)return;
 const preferred=['Código','Evidência / Documento','Plano','Norma','Órgão que cobra','Status','Responsável','Obrigatório?','Tipo de evidência','Base legal (lei / norma)','Periodicidade de renovação','Renovar a cada (meses)','Data de emissão','Data de validade','Dias para vencer','Local / link do arquivo','Observações'];
 const rows=preferred.map(k=>{let v=e[k]||'';if(k==='Dias para vencer')v=String(evidenceDays(e)||'');if(k==='Data de emissão'||k==='Data de validade')v=v?date(v):'';return `<div class="ev-detail"><span>${esc(k)}</span><strong>${esc(v||'Não informado')}</strong></div>`}).join('');
 const hasLink=!!e['Local / link do arquivo'];
 const dlg=$('#evidenceDialog');dlg.dataset.code=code;
 dlg.innerHTML=`<div class="ev-detail-modal"><div class="dialoghead"><div><small class="ev-detail-code">${esc(code)}</small><h2>${esc(e['Evidência / Documento'])}</h2></div><button type="button" class="iconbtn" data-evidence-close>✕</button></div><div class="ev-detail-summary"><span class="ev-pill ${evidenceColor(evidenceStatus(e))}">${esc(evidenceStatus(e))}</span><span>${esc(e.Plano||'Sem plano')}</span><span>${esc(e.Norma||'Sem norma')}</span></div><div class="ev-detail-grid">${rows}</div><div class="dialogactions">${hasLink?`<button type="button" class="secondary" data-evidence-openlink="${esc(code)}">↗ Ir para link</button><button type="button" class="secondary" data-evidence-copylink="${esc(code)}">⧉ Copiar link</button>`:''}<button type="button" class="secondary" data-evidence-close>Fechar</button><button type="button" class="primary" data-evidence-edit="${esc(code)}">Editar evidência</button></div></div>`;
 dlg.showModal();
}
function evidenceLink(code,action){
 const e=evidences.find(x=>x['Código']===code);const raw=e?.['Local / link do arquivo']?.trim();if(!raw){toast('Nenhum link cadastrado.');return}
 if(action==='copy'){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(raw).then(()=>toast('Link copiado!')).catch(()=>prompt('Copie o endereço:',raw))}else prompt('Copie o endereço:',raw);return}
 // Apenas links web seguros podem ser abertos pelo navegador. Caminhos de rede podem ser copiados.
 let url;try{url=new URL(raw)}catch(_){toast('Este é um caminho de arquivo. Use Copiar link para acessá-lo na rede.');return}
 if(!['https:','http:'].includes(url.protocol)){toast('Somente links HTTP ou HTTPS podem ser abertos. Use Copiar link.');return}
 window.open(url.href,'_blank','noopener,noreferrer');
}
function evidenceOpen(code=''){
 const e=evidences.find(x=>x['Código']===code)||Object.fromEntries(EH.map(h=>[h,'']));if(!code)e['Código']='Gerado ao salvar';
 const planList=evidencePlans().map(p=>`<option value="${esc(p)}">`).join('');
 const html=evidenceFields.map(([field,type])=>{const val=e[field]||'',id='evf'+EH.indexOf(field);let input='';if(type==='textarea')input=`<textarea id="${id}" rows="2">${esc(val)}</textarea>`;else if(type==='plan')input=`<input id="${id}" list="evidencePlansList" value="${esc(val)}" placeholder="Selecione ou digite um plano"><datalist id="evidencePlansList">${planList}</datalist>`;else if(type.startsWith('select:'))input=`<select id="${id}">${type.slice(7).split('|').map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else input=`<input id="${id}" type="${type==='readonly'?'text':type}" ${type==='readonly'||field==='Código'?'readonly':''} value="${esc(val)}" ${field==='Evidência / Documento'?'required':''}>`;return `<label class="${type==='textarea'||field==='Evidência / Documento'?'ev-wide':''}">${esc(field)}${input}</label>`}).join('');
 const dlg=$('#evidenceDialog');dlg.innerHTML=`<form id="evidenceForm"><div class="dialoghead"><h2>${code?'Editar evidência':'Cadastrar evidência'}</h2><button type="button" class="iconbtn" data-evidence-close>✕</button></div><div class="ev-formgrid">${html}</div><div class="dialogactions">${code?'<button type="button" class="danger" data-evidence-delete>Excluir evidência</button>':''}<button type="button" class="secondary" data-evidence-close>Cancelar</button><button class="primary" type="submit">Salvar evidência</button></div></form>`;
 dlg.dataset.code=code;dlg.showModal();
 const emission=$('#evf'+EH.indexOf('Data de emissão')),months=$('#evf'+EH.indexOf('Renovar a cada (meses)')),expiry=$('#evf'+EH.indexOf('Data de validade'));
 function calculate(){if(emission.value&&months.value&&!expiry.value){const d=new Date(emission.value+'T12:00:00');const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(months.value));const max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,max));expiry.value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}const v=expiry.value;$('#evf'+EH.indexOf('Dias para vencer')).value=v?evidenceDays({'Data de validade':v}):''}
 emission.addEventListener('change',calculate);months.addEventListener('change',calculate);expiry.addEventListener('change',calculate);calculate();
}
function evidenceSave(ev){ev.preventDefault();const code=$('#evidenceDialog').dataset.code;const item={};EH.forEach((h,i)=>item[h]=$('#evf'+i).value.trim());if(!item['Evidência / Documento'])return;item['Código']=code||evidenceNextCode();item.Plano=item.Plano.toLocaleUpperCase('pt-BR');item['Dias para vencer']=String(evidenceDays(item));if(item.Plano&&!plans.some(p=>p.plano===item.Plano))plans.push({plano:item.Plano,descricao:'',responsavel:''});const idx=evidences.findIndex(e=>e['Código']===code);if(idx>=0)evidences[idx]=item;else evidences.push(item);$('#evidenceDialog').close();changed();toast('Evidência '+item['Código']+' salva')}
function evidenceImport(){const existing=new Set(evidences.map(e=>norm(e.Norma+'|'+e['Evidência / Documento'])));const pending=EVIDENCE_MODEL.filter(e=>!existing.has(norm(e.Norma+'|'+e['Evidência / Documento'])));if(!pending.length){toast('Todas as evidências da lista já estão cadastradas.');return}if(!confirm(`Importar ${pending.length} evidências da lista enviada? Elas serão acrescentadas ao Excel conectado com códigos automáticos.`))return;pending.forEach(x=>{const e={...x};e['Código']=evidenceNextCode();evidences.push(e);if(e.Plano&&!plans.some(p=>p.plano===e.Plano))plans.push({plano:e.Plano,descricao:'',responsavel:''})});changed();toast(`${pending.length} evidências importadas`)}
$('#evidenceDialog').addEventListener('click',e=>{if(e.target.closest('[data-evidence-close]'))$('#evidenceDialog').close();const view=e.target.closest('[data-evidence-edit]');if(view){const code=view.dataset.evidenceEdit;$('#evidenceDialog').close();evidenceOpen(code)}const open=e.target.closest('[data-evidence-openlink]');if(open)evidenceLink(open.dataset.evidenceOpenlink,'open');const copy=e.target.closest('[data-evidence-copylink]');if(copy)evidenceLink(copy.dataset.evidenceCopylink,'copy');if(e.target.closest('[data-evidence-delete]')){const code=$('#evidenceDialog').dataset.code;if(confirm('Excluir a evidência '+code+'?')){evidences=evidences.filter(x=>x['Código']!==code);$('#evidenceDialog').close();changed()}}});
$('#evidenceDialog').addEventListener('submit',e=>{if(e.target.id==='evidenceForm')evidenceSave(e)});

